1	"use client";
2	
3	import { useState, type FormEvent } from "react";
4	import { useRouter } from "next/navigation";
5	import { openShift } from "./actions";
6	import SwitchCashierButton from "./switch-cashier-button";
7	
8	export default function OpenShiftScreen({
9	  businessId,
10	  businessName,
11	  cashierId,
12	  cashierName,
13	}: {
14	  businessId: string;
15	  businessName: string;
16	  cashierId: string;
17	  cashierName: string;
18	}) {
19	  const router = useRouter();
20	  const [openingCash, setOpeningCash] = useState("");
21	  const [notes, setNotes] = useState("");
22	  const [error, setError] = useState<string | null>(null);
23	  const [submitting, setSubmitting] = useState(false);
24	
25	  async function handleSubmit(e: FormEvent) {
26	    e.preventDefault();
27	    setError(null);
28	
29	    const amount = Number(openingCash);
30	    if (!openingCash || Number.isNaN(amount) || amount < 0) {
31	      setError("Modal awal harus angka dan tidak boleh negatif.");
32	      return;
33	    }
34	
35	    setSubmitting(true);
36	    const result = await openShift(businessId, cashierId, amount, notes);
37	    setSubmitting(false);
38	
39	    if (!result.success) {
40	      setError(result.error);
41	      return;
42	    }
43	
44	    router.refresh();
45	  }
46	
47	  return (
48	    <div className="flex flex-1 items-center justify-center bg-zinc-50 px-4">
49	      <div className="w-full max-w-sm rounded-xl bg-white shadow-sm p-6">
50	        <div className="mb-6 text-center">
51	          <div className="mx-auto mb-3 flex h-12 w-12 items-center justify-center rounded-2xl bg-brand-600">
52	            <span className="text-lg font-bold text-white">🟢</span>
53	          </div>
54	          <h1 className="text-lg font-bold text-zinc-900">Mulai Shift</h1>
55	          <p className="mt-1 text-sm text-zinc-500">
56	            {cashierName} — {businessName}
57	          </p>
58	          <p className="mt-1 text-xs text-zinc-400">
59	            Belum ada shift aktif. Catat modal awal di laci sebelum mulai jualan.
60	          </p>
61	        </div>
62	
63	        <form onSubmit={handleSubmit} className="space-y-4">
64	          <div>
65	            <label htmlFor="openingCash" className="mb-1 block text-xs font-medium text-zinc-600">
66	              Modal Awal (Rp)
67	            </label>
68	            <input
69	              id="openingCash"
70	              type="number"
71	              min="0"
72	              value={openingCash}
73	              onChange={(e) => setOpeningCash(e.target.value)}
74	              required
75	              className="w-full rounded-xl border border-zinc-200 px-3.5 py-2.5 text-sm focus:border-brand-600 focus:outline-none focus:ring-2 focus:ring-brand-100"
76	              placeholder="mis. 300000"
77	            />
78	          </div>
79	          <div>
80	            <label htmlFor="notes" className="mb-1 block text-xs font-medium text-zinc-600">
81	              Catatan (opsional)
82	            </label>
83	            <input
84	              id="notes"
85	              type="text"
86	              value={notes}
87	              onChange={(e) => setNotes(e.target.value)}
88	              className="w-full rounded-xl border border-zinc-200 px-3.5 py-2.5 text-sm focus:border-brand-600 focus:outline-none focus:ring-2 focus:ring-brand-100"
89	              placeholder="mis. Shift pagi"
90	            />
91	          </div>
92	
93	          {error && (
94	            <p className="rounded-lg bg-red-50 px-3 py-2 text-xs text-red-600">{error}</p>
95	          )}
96	
97	          <button
98	            type="submit"
99	            disabled={submitting}
100	            className="w-full rounded-xl bg-brand-600 py-2.5 text-sm font-semibold text-white transition-colors hover:bg-brand-700 disabled:cursor-not-allowed disabled:opacity-60"
101	          >
102	            {submitting ? "Memproses…" : "Mulai Shift"}
103	          </button>
104	        </form>
105	
106	        <SwitchCashierButton />
107	      </div>
108	    </div>
109	  );
110	}
111

1	import { notFound } from "next/navigation";
2	import { createClient } from "@/lib/supabase/server";
3	
4	function formatRupiah(value: number) {
5	  return `Rp${Math.round(value).toLocaleString("id-ID")}`;
6	}
7	
8	function formatDateTime(iso: string) {
9	  return new Date(iso).toLocaleString("id-ID", {
10	    day: "2-digit",
11	    month: "short",
12	    hour: "2-digit",
13	    minute: "2-digit",
14	  });
15	}
16	
17	type ShiftRow = {
18	  id: string;
19	  opened_at: string;
20	  closed_at: string;
21	  opening_cash: number;
22	  closing_cash: number;
23	  cash_sales: number;
24	  non_cash_sales: number;
25	  total_sales: number;
26	  expected_cash: number;
27	  difference: number;
28	  tx_count: number;
29	  void_count: number;
30	  close_notes: string | null;
31	  cashiers: { name: string } | null;
32	};
33	
34	export default async function ShiftsPage({
35	  params,
36	}: {
37	  params: Promise<{ businessId: string }>;
38	}) {
39	  const { businessId } = await params;
40	  const supabase = await createClient();
41	
42	  const { data: business } = await supabase
43	    .from("businesses")
44	    .select("id, name")
45	    .eq("id", businessId)
46	    .single();
47	
48	  if (!business) {
49	    notFound();
50	  }
51	
52	  const { data: shiftRows } = await supabase
53	    .from("shifts")
54	    .select(
55	      "id, opened_at, closed_at, opening_cash, closing_cash, cash_sales, non_cash_sales, total_sales, expected_cash, difference, tx_count, void_count, close_notes, cashiers(name)",
56	    )
57	    .eq("business_id", businessId)
58	    .not("closed_at", "is", null)
59	    .order("closed_at", { ascending: false })
60	    .limit(50);
61	
62	  const shifts = (shiftRows ?? []) as unknown as ShiftRow[];
63	
64	  return (
65	    <div className="w-full max-w-2xl">
66	        <h1 className="text-lg font-bold text-zinc-900">
67	          Riwayat Shift — {business.name}
68	        </h1>
69	        <p className="mt-1 text-sm text-zinc-500">50 shift terakhir yang sudah ditutup.</p>
70	
71	        <div className="mt-6 space-y-2">
72	          {shifts.length > 0 ? (
73	            shifts.map((s) => {
74	              const diff = Number(s.difference);
75	              return (
76	                <div
77	                  key={s.id}
78	                  className="rounded-xl border border-zinc-200 bg-white px-4 py-3"
79	                >
80	                  <div className="flex items-center justify-between">
81	                    <p className="text-sm font-medium text-zinc-900">
82	                      {s.cashiers?.name ?? "Kasir terhapus"}
83	                    </p>
84	                    <p className="text-sm font-semibold text-zinc-900">
85	                      {formatRupiah(Number(s.total_sales))}
86	                    </p>
87	                  </div>
88	                  <p className="mt-0.5 text-xs text-zinc-500">
89	                    {formatDateTime(s.opened_at)} – {formatDateTime(s.closed_at)}
90	                  </p>
91	
92	                  <div className="mt-2 grid grid-cols-3 gap-2 rounded-lg bg-zinc-50 px-3 py-2 text-center">
93	                    <div>
94	                      <p className="text-[10px] text-zinc-400">Transaksi</p>
95	                      <p className="text-xs font-semibold text-zinc-900">{s.tx_count}</p>
96	                    </div>
97	                    <div>
98	                      <p className="text-[10px] text-zinc-400">Kas Diharapkan</p>
99	                      <p className="text-xs font-semibold text-zinc-900">
100	                        {formatRupiah(Number(s.expected_cash))}
101	                      </p>
102	                    </div>
103	                    <div>
104	                      <p className="text-[10px] text-zinc-400">Selisih</p>
105	                      <p
106	                        className={`text-xs font-semibold ${
107	                          diff === 0
108	                            ? "text-zinc-900"
109	                            : diff > 0
110	                              ? "text-brand-700"
111	                              : "text-red-600"
112	                        }`}
113	                      >
114	                        {diff === 0 ? "Pas" : `${diff > 0 ? "+" : ""}${formatRupiah(diff)}`}
115	                      </p>
116	                    </div>
117	                  </div>
118	
119	                  {s.void_count > 0 && (
120	                    <p className="mt-1.5 text-[11px] text-red-500">
121	                      {s.void_count} transaksi dibatalkan
122	                    </p>
123	                  )}
124	                  {s.close_notes && (
125	                    <p className="mt-1.5 text-[11px] text-zinc-400">Catatan: {s.close_notes}</p>
126	                  )}
127	                </div>
128	              );
129	            })
130	          ) : (
131	            <p className="rounded-xl border border-dashed border-zinc-200 px-4 py-6 text-center text-xs text-zinc-400">
132	              Belum ada shift yang ditutup.
133	            </p>
134	          )}
135	        </div>
136	    </div>
137	  );
138	}
