1	"use client";
2	
3	import { useEffect, useMemo, useState, type KeyboardEvent } from "react";
4	import { useRouter } from "next/navigation";
5	import Link from "next/link";
6	import {
7	  checkout,
8	  closeShift,
9	  deleteOpenBill,
10	  saveOpenBill,
11	  updateSelfOrderStatus,
12	  type CheckoutResult,
13	  type CloseShiftSummary,
14	  type DiscountType,
15	} from "./actions";
16	import SwitchCashierButton from "./switch-cashier-button";
17	import OfflineStatus from "./offline-status";
18	import { itemDiscAmount, calculateCheckoutTotals } from "@/lib/checkout-totals";
19	import { useOfflineSync } from "@/hooks/use-offline-sync";
20	import { enqueueSale, pendingStockDeltas } from "@/lib/offline-queue";
21	import { withTimeout } from "@/lib/with-timeout";
22	
23	type Product = {
24	  id: string;
25	  name: string;
26	  category: string | null;
27	  price: number;
28	  cost: number;
29	  stock: number;
30	  emoji: string | null;
31	  barcode: string | null;
32	  sku: string | null;
33	  variant_label: string | null;
34	};
35	
36	type CartItem = {
37	  productId: string;
38	  name: string;
39	  price: number;
40	  qty: number;
41	  maxStock: number;
42	  disc: number;
43	  discType: DiscountType;
44	};
45	
46	type SelfOrder = {
47	  id: string;
48	  status: "baru" | "diproses";
49	  createdAt: string;
50	  tableName: string;
51	  items: {
52	    productId: string | null;
53	    name: string;
54	    qty: number;
55	    price: number;
56	    note: string | null;
57	  }[];
58	};
59	
60	type OpenBill = {
61	  id: string;
62	  label: string;
63	  updated_at: string;
64	  items: {
65	    product_id: string;
66	    name: string;
67	    price: number;
68	    qty: number;
69	    disc: number;
70	    disc_type: DiscountType;
71	  }[];
72	};
73	
74	type Customer = {
75	  id: string;
76	  name: string;
77	  phone: string | null;
78	};
79	
80	const BUILTIN_PAYMENT_METHODS = ["Tunai", "Kartu", "QRIS"];
81	
82	function formatRupiah(value: number) {
83	  return `Rp${value.toLocaleString("id-ID")}`;
84	}
85	
86	export default function PosScreen({
87	  businessId,
88	  businessName,
89	  cashierId,
90	  cashierName,
91	  shiftId,
92	  products,
93	  taxRate,
94	  serviceRate,
95	  openBills,
96	  customers,
97	  isFnb,
98	  selfOrders,
99	  customPaymentMethods,
100	}: {
101	  businessId: string;
102	  businessName: string;
103	  cashierId: string;
104	  cashierName: string;
105	  shiftId: string;
106	  products: Product[];
107	  taxRate: number;
108	  serviceRate: number;
109	  openBills: OpenBill[];
110	  customers: Customer[];
111	  isFnb: boolean;
112	  selfOrders: SelfOrder[];
113	  customPaymentMethods: string[];
114	}) {
115	  const router = useRouter();
116	  const paymentMethods = useMemo(
117	    () => [...BUILTIN_PAYMENT_METHODS, ...customPaymentMethods],
118	    [customPaymentMethods],
119	  );
120	  const [search, setSearch] = useState("");
121	  const [scanFeedback, setScanFeedback] = useState<string | null>(null);
122	  const [cart, setCart] = useState<CartItem[]>([]);
123	  const [cartOrderIds, setCartOrderIds] = useState<string[]>([]);
124	  const [inboxOpen, setInboxOpen] = useState(false);
125	  const [inboxNotice, setInboxNotice] = useState<string | null>(null);
126	  const [orderBusyId, setOrderBusyId] = useState<string | null>(null);
127	  const [editingDiscId, setEditingDiscId] = useState<string | null>(null);
128	  const [orderDisc, setOrderDisc] = useState(0);
129	  const [orderDiscType, setOrderDiscType] = useState<DiscountType>("pct");
130	  const [orderDiscOpen, setOrderDiscOpen] = useState(false);
131	  const [selectedCustomer, setSelectedCustomer] = useState<Customer | null>(null);
132	  const [customerPickerOpen, setCustomerPickerOpen] = useState(false);
133	  const [customerSearch, setCustomerSearch] = useState("");
134	  const [billsOpen, setBillsOpen] = useState(false);
135	  const [billBusyId, setBillBusyId] = useState<string | null>(null);
136	  const [activeBill, setActiveBill] = useState<{ id: string; label: string } | null>(null);
137	  const [saveBonOpen, setSaveBonOpen] = useState(false);
138	  const [bonLabel, setBonLabel] = useState("");
139	  const [bonError, setBonError] = useState<string | null>(null);
140	  const [bonSaving, setBonSaving] = useState(false);
141	
142	  const newOrderCount = selfOrders.filter((o) => o.status === "baru").length;
143	
144	  // Order self-order masuk dari perangkat pelanggan; poll supaya badge kasir
145	  // ikut terbarui tanpa reload manual. router.refresh() mempertahankan state
146	  // client (keranjang tidak hilang).
147	  useEffect(() => {
148	    if (!isFnb) return;
149	    const interval = setInterval(() => router.refresh(), 15000);
150	    return () => clearInterval(interval);
151	  }, [isFnb, router]);
152	  const [paying, setPaying] = useState(false);
153	  const [paymentMethod, setPaymentMethod] = useState(BUILTIN_PAYMENT_METHODS[0]);
154	  const [received, setReceived] = useState("");
155	  const [submitting, setSubmitting] = useState(false);
156	  const [error, setError] = useState<string | null>(null);
157	  const [successInvoice, setSuccessInvoice] = useState<string | null>(null);
158	  const [successTransactionId, setSuccessTransactionId] = useState<string | null>(null);
159	  const [successOffline, setSuccessOffline] = useState(false);
160	
161	  const { isOnline, pending, syncNow, discard } = useOfflineSync(businessId);
162	  const effectiveProducts = useMemo(() => {
163	    const deltas = pendingStockDeltas(pending);
164	    if (Object.keys(deltas).length === 0) return products;
165	    return products.map((p) =>
166	      deltas[p.id] ? { ...p, stock: Math.max(0, p.stock - deltas[p.id]) } : p,
167	    );
168	  }, [products, pending]);
169	
170	  const [closingShift, setClosingShift] = useState(false);
171	  const [closingCash, setClosingCash] = useState("");
172	  const [closeNotes, setCloseNotes] = useState("");
173	  const [closeError, setCloseError] = useState<string | null>(null);
174	  const [closeSubmitting, setCloseSubmitting] = useState(false);
175	  const [closedSummary, setClosedSummary] = useState<CloseShiftSummary | null>(null);
176	
177	  const filteredProducts = useMemo(() => {
178	    const q = search.trim().toLowerCase();
179	    if (!q) return effectiveProducts;
180	    return effectiveProducts.filter(
181	      (p) =>
182	        p.name.toLowerCase().includes(q) ||
183	        p.barcode?.toLowerCase() === q ||
184	        p.sku?.toLowerCase() === q,
185	    );
186	  }, [search, effectiveProducts]);
187	
188	  // Variants are just extra product rows sharing the same name — group them
189	  // here purely for display, no schema relationship involved.
190	  const productGroups = useMemo(() => {
191	    const groups: { name: string; variants: Product[] }[] = [];
192	    for (const p of filteredProducts) {
193	      const existing = groups.find((g) => g.name === p.name);
194	      if (existing) {
195	        existing.variants.push(p);
196	      } else {
197	        groups.push({ name: p.name, variants: [p] });
198	      }
199	    }
200	    return groups;
201	  }, [filteredProducts]);
202	
203	  const [variantPickerGroup, setVariantPickerGroup] = useState<{
204	    name: string;
205	    variants: Product[];
206	  } | null>(null);
207	
208	  function handleProductClick(group: { name: string; variants: Product[] }) {
209	    if (group.variants.length === 1) {
210	      addToCart(group.variants[0]);
211	    } else {
212	      setVariantPickerGroup(group);
213	    }
214	  }
215	
216	  // Barcode scanners act like a keyboard: they type the code then send
217	  // Enter. On Enter, an exact barcode/SKU match jumps straight into the cart
218	  // instead of just filtering the grid.
219	  useEffect(() => {
220	    if (!scanFeedback) return;
221	    const timer = setTimeout(() => setScanFeedback(null), 2500);
222	    return () => clearTimeout(timer);
223	  }, [scanFeedback]);
224	
225	  function handleSearchKeyDown(e: KeyboardEvent<HTMLInputElement>) {
226	    if (e.key !== "Enter") return;
227	    const q = search.trim();
228	    if (!q) return;
229	    const match = effectiveProducts.find((p) => p.barcode === q || p.sku === q);
230	    if (match) {
231	      addToCart(match);
232	      setSearch("");
233	      setScanFeedback(null);
234	    } else if (effectiveProducts.some((p) => p.barcode || p.sku)) {
235	      setScanFeedback(`"${q}" tidak ditemukan.`);
236	    }
237	  }
238	
239	  const filteredCustomers = useMemo(() => {
240	    const q = customerSearch.trim().toLowerCase();
241	    if (!q) return customers;
242	    return customers.filter(
243	      (c) => c.name.toLowerCase().includes(q) || c.phone?.toLowerCase().includes(q),
244	    );
245	  }, [customerSearch, customers]);
246	
247	  const { subtotalRaw, totalItemDisc, afterItemDisc, orderDiscAmt, serviceAmt, taxAmt, total } =
248	    calculateCheckoutTotals({
249	      items: cart,
250	      orderDisc,
251	      orderDiscType,
252	      serviceRate,
253	      taxRate,
254	    });
255	  const receivedAmount = Number(received) || 0;
256	  const change = paymentMethod === "Tunai" ? receivedAmount - total : 0;
257	
258	  function addToCart(product: Product) {
259	    setCart((prev) => {
260	      const existing = prev.find((i) => i.productId === product.id);
261	      if (existing) {
262	        if (existing.qty >= product.stock) return prev;
263	        return prev.map((i) =>
264	          i.productId === product.id ? { ...i, qty: i.qty + 1 } : i,
265	        );
266	      }
267	      if (product.stock <= 0) return prev;
268	      return [
269	        ...prev,
270	        {
271	          productId: product.id,
272	          name: product.variant_label ? `${product.name} (${product.variant_label})` : product.name,
273	          price: product.price,
274	          qty: 1,
275	          maxStock: product.stock,
276	          disc: 0,
277	          discType: "pct" as DiscountType,
278	        },
279	      ];
280	    });
281	  }
282	
283	  function setItemDisc(productId: string, disc: number, discType: DiscountType) {
284	    setCart((prev) =>
285	      prev.map((i) => (i.productId === productId ? { ...i, disc, discType } : i)),
286	    );
287	  }
288	
289	  function changeQty(productId: string, delta: number) {
290	    setCart((prev) =>
291	      prev
292	        .map((i) =>
293	          i.productId === productId
294	            ? { ...i, qty: Math.min(i.maxStock, Math.max(0, i.qty + delta)) }
295	            : i,
296	        )
297	        .filter((i) => i.qty > 0),
298	    );
299	  }
300	
301	  function removeFromCart(productId: string) {
302	    setCart((prev) => prev.filter((i) => i.productId !== productId));
303	  }
304	
305	  async function handleSaveBon() {
306	    setBonError(null);
307	    setBonSaving(true);
308	    const result = await saveOpenBill(
309	      businessId,
310	      activeBill?.id ?? null,
311	      bonLabel,
312	      cart.map((i) => ({
313	        product_id: i.productId,
314	        name: i.name,
315	        price: i.price,
316	        qty: i.qty,
317	        disc: i.disc,
318	        disc_type: i.discType,
319	      })),
320	    );
321	    setBonSaving(false);
322	
323	    if (!result.success) {
324	      setBonError(result.error);
325	      return;
326	    }
327	
328	    setCart([]);
329	    setCartOrderIds([]);
330	    setOrderDisc(0);
331	    setOrderDiscType("pct");
332	    setActiveBill(null);
333	    setSaveBonOpen(false);
334	    setBonLabel("");
335	    router.refresh();
336	  }
337	
338	  function handleLoadBill(bill: OpenBill) {
339	    if (
340	      cart.length > 0 &&
341	      !window.confirm(`Keranjang aktif akan digabung dengan "${bill.label}". Lanjutkan?`)
342	    ) {
343	      return;
344	    }
345	
346	    const next = cart.map((c) => ({ ...c }));
347	    const skipped: string[] = [];
348	
349	    for (const item of bill.items) {
350	      const product = effectiveProducts.find((p) => p.id === item.product_id);
351	      if (!product) {
352	        skipped.push(item.name);
353	        continue;
354	      }
355	      const existing = next.find((c) => c.productId === product.id);
356	      const currentQty = existing ? existing.qty : 0;
357	      const addQty = Math.min(item.qty, product.stock - currentQty);
358	      if (addQty <= 0) {
359	        skipped.push(item.name);
360	        continue;
361	      }
362	      if (existing) {
363	        existing.qty += addQty;
364	      } else {
365	        next.push({
366	          productId: product.id,
367	          name: product.name,
368	          price: product.price,
369	          qty: addQty,
370	          maxStock: product.stock,
371	          disc: item.disc,
372	          discType: item.disc_type,
373	        });
374	      }
375	    }
376	
377	    setCart(next);
378	    setActiveBill({ id: bill.id, label: bill.label });
379	    setInboxNotice(
380	      skipped.length > 0
