403	  async function handleAddOrderToCart(order: SelfOrder) {
404	    const next = cart.map((c) => ({ ...c }));
405	    const skipped: string[] = [];
406	
407	    for (const item of order.items) {
408	      const product = item.productId
409	        ? effectiveProducts.find((p) => p.id === item.productId)
410	        : undefined;
411	      if (!product) {
412	        skipped.push(item.name);
413	        continue;
414	      }
415	      const existing = next.find((c) => c.productId === product.id);
416	      const currentQty = existing ? existing.qty : 0;
417	      const addQty = Math.min(item.qty, product.stock - currentQty);
418	      if (addQty <= 0) {
419	        skipped.push(item.name);
420	        continue;
421	      }
422	      if (existing) {
423	        existing.qty += addQty;
424	      } else {
425	        next.push({
426	          productId: product.id,
427	          name: product.name,
428	          price: product.price,
429	          qty: addQty,
430	          maxStock: product.stock,
431	          disc: 0,
432	          discType: "pct",
433	        });
434	      }
435	    }
436	
437	    setCart(next);
438	    setCartOrderIds((prev) => (prev.includes(order.id) ? prev : [...prev, order.id]));
439	    setInboxNotice(
440	      skipped.length > 0
441	        ? `Tidak masuk keranjang (stok habis / produk terhapus): ${skipped.join(", ")}`
442	        : null,
443	    );
444	    setInboxOpen(false);
445	    await handleOrderStatus(order.id, "diproses");
446	  }
