1	-- Module 9: shift open/close as RPCs, so the cash reconciliation math
2	-- (expected cash, difference, totals) is computed once in the database
3	-- instead of being re-derived in the browser and trusted blindly.
4	
5	create or replace function public.open_shift(
6	  p_business_id uuid,
7	  p_cashier_id uuid,
8	  p_opening_cash numeric,
9	  p_notes text default null
10	)
11	returns uuid
12	language plpgsql
13	security definer
14	set search_path = ''
15	as $$
16	declare
17	  v_shift_id uuid;
18	begin
19	  if not private.owns_business(p_business_id) then
20	    raise exception 'not authorized';
21	  end if;
22	
23	  if not exists (
24	    select 1 from public.cashiers c
25	    where c.id = p_cashier_id and c.business_id = p_business_id and c.active
26	  ) then
27	    raise exception 'invalid cashier';
28	  end if;
29	
30	  if exists (
31	    select 1 from public.shifts s
32	    where s.business_id = p_business_id and s.closed_at is null
33	  ) then
34	    raise exception 'a shift is already open for this business';
35	  end if;
36	
37	  if p_opening_cash is null or p_opening_cash < 0 then
38	    raise exception 'invalid opening cash';
39	  end if;
40	
41	  insert into public.shifts (business_id, cashier_id, opening_cash, notes)
42	  values (p_business_id, p_cashier_id, p_opening_cash, p_notes)
43	  returning id into v_shift_id;
44	
45	  return v_shift_id;
46	end;
47	$$;
48	
49	grant execute on function public.open_shift(uuid, uuid, numeric, text) to authenticated;
50	
51	-- Close a shift: tallies non-voided transactions recorded against it, then
52	-- stamps the shift row with the computed totals and the cash difference.
53	create or replace function public.close_shift(
54	  p_shift_id uuid,
55	  p_closing_cash numeric,
56	  p_close_notes text default null
57	)
58	returns table (
59	  cash_sales numeric,
60	  non_cash_sales numeric,
61	  total_sales numeric,
62	  expected_cash numeric,
63	  difference numeric,
64	  tx_count int,
65	  void_count int
66	)
67	language plpgsql
68	security definer
69	set search_path = ''
70	as $$
71	declare
72	  v_business_id uuid;
73	  v_opening_cash numeric(12, 2);
74	  v_cash_sales numeric(12, 2) := 0;
75	  v_non_cash_sales numeric(12, 2) := 0;
76	  v_tx_count int := 0;
77	  v_void_count int := 0;
78	begin
79	  select s.business_id, s.opening_cash into v_business_id, v_opening_cash
80	  from public.shifts s
81	  where s.id = p_shift_id and s.closed_at is null;
82	
83	  if not found then
84	    raise exception 'shift not found or already closed';
85	  end if;
86	
87	  if not private.owns_business(v_business_id) then
88	    raise exception 'not authorized';
89	  end if;
90	
91	  if p_closing_cash is null or p_closing_cash < 0 then
92	    raise exception 'invalid closing cash';
93	  end if;
94	
95	  select
96	    coalesce(sum(tp.amount) filter (where tp.method = 'Tunai'), 0),
97	    coalesce(sum(tp.amount) filter (where tp.method != 'Tunai'), 0)
98	  into v_cash_sales, v_non_cash_sales
99	  from public.transactions t
100	  join public.transaction_payments tp on tp.transaction_id = t.id
101	  where t.shift_id = p_shift_id and not t.voided;
102	
103	  select
104	    count(*) filter (where not t.voided),
105	    count(*) filter (where t.voided)
106	  into v_tx_count, v_void_count
107	  from public.transactions t
108	  where t.shift_id = p_shift_id;
109	
110	  update public.shifts s
111	  set closed_at = now(),
112	      closing_cash = p_closing_cash,
113	      close_notes = p_close_notes,
114	      cash_sales = v_cash_sales,
115	      non_cash_sales = v_non_cash_sales,
116	      total_sales = v_cash_sales + v_non_cash_sales,
117	      expected_cash = v_opening_cash + v_cash_sales,
118	      difference = p_closing_cash - (v_opening_cash + v_cash_sales),
119	      tx_count = v_tx_count,
120	      void_count = v_void_count
121	  where s.id = p_shift_id;
122	
123	  return query
124	  select
125	    v_cash_sales,
126	    v_non_cash_sales,
127	    v_cash_sales + v_non_cash_sales,
128	    v_opening_cash + v_cash_sales,
129	    p_closing_cash - (v_opening_cash + v_cash_sales),
130	    v_tx_count,
131	    v_void_count;
132	end;
133	$$;
134	
135	grant execute on function public.close_shift(uuid, numeric, text) to authenticated;
136	
137	-- Attach transactions to whichever shift is currently open for the
138	-- business, looked up server-side (never trusted from the client).
139	create or replace function public.checkout_transaction(
140	  p_business_id uuid,
141	  p_cashier_id uuid,
142	  p_items jsonb, -- array of {product_id, qty}
143	  p_payment_method text,
144	  p_received numeric default null
145	)
146	returns table (transaction_id uuid, invoice_number text)
147	language plpgsql
148	security definer
149	set search_path = ''
150	as $$
151	declare
152	  v_invoice_number text;
153	  v_seq int;
154	  v_subtotal numeric(12, 2) := 0;
155	  v_total_cost numeric(12, 2) := 0;
156	  v_transaction_id uuid;
157	  v_item jsonb;
158	  v_qty numeric(12, 2);
159	  v_product_id uuid;
160	  v_product record;
161	  v_change numeric(12, 2);
162	  v_shift_id uuid;
163	begin
164	  if not private.owns_business(p_business_id) then
165	    raise exception 'not authorized';
166	  end if;
167	
168	  if not exists (
169	    select 1 from public.cashiers c
170	    where c.id = p_cashier_id and c.business_id = p_business_id and c.active
171	  ) then
172	    raise exception 'invalid cashier';
173	  end if;
174	
175	  if p_payment_method is null or length(trim(p_payment_method)) = 0 then
176	    raise exception 'payment method required';
177	  end if;
178	
179	  if p_items is null or jsonb_array_length(p_items) = 0 then
180	    raise exception 'cart is empty';
181	  end if;
182	
183	  select id into v_shift_id
184	  from public.shifts
185	  where business_id = p_business_id and closed_at is null
186	  limit 1;
187	
188	  if v_shift_id is null then
189	    raise exception 'no active shift — open a shift before selling';
190	  end if;
191	
192	  select count(*) + 1 into v_seq
193	  from public.transactions t
194	  where t.business_id = p_business_id
195	    and t.date::date = current_date;
196	
197	  v_invoice_number := 'INV-' || to_char(current_date, 'YYYYMMDD') || '-' || lpad(v_seq::text, 4, '0');
198	
199	  insert into public.transactions (
200	    business_id, shift_id, cashier_id, invoice_number, date,
201	    subtotal_raw, subtotal, total, total_cost, gross_profit
202	  ) values (
203	    p_business_id, v_shift_id, p_cashier_id, v_invoice_number, now(),
204	    0, 0, 0, 0, 0
205	  )
206	  returning id into v_transaction_id;
207	
208	  for v_item in select * from jsonb_array_elements(p_items)
209	  loop
210	    v_product_id := (v_item ->> 'product_id')::uuid;
211	    v_qty := (v_item ->> 'qty')::numeric;
212	
213	    if v_qty is null or v_qty <= 0 then
214	      raise exception 'invalid quantity';
215	    end if;
216	
217	    select * into v_product
218	    from public.products p
219	    where p.id = v_product_id
220	      and p.business_id = p_business_id
221	      and p.deleted_at is null;
222	
223	    if not found then
224	      raise exception 'product not found: %', v_product_id;
225	    end if;
226	
227	    insert into public.transaction_items (
228	      transaction_id, product_id, name, category, price, cost, qty
229	    ) values (
230	      v_transaction_id, v_product.id, v_product.name, v_product.category,
231	      v_product.price, v_product.cost, v_qty
232	    );
233	
234	    update public.products
235	    set stock = greatest(0, stock - v_qty)
236	    where id = v_product_id;
237	
238	    v_subtotal := v_subtotal + v_product.price * v_qty;
239	    v_total_cost := v_total_cost + v_product.cost * v_qty;
240	  end loop;
241	
242	  update public.transactions
243	  set subtotal_raw = v_subtotal,
244	      subtotal = v_subtotal,
245	      total = v_subtotal,
246	      total_cost = v_total_cost,
247	      gross_profit = v_subtotal - v_total_cost
248	  where id = v_transaction_id;
249	
250	  v_change := greatest(coalesce(p_received, v_subtotal) - v_subtotal, 0);
251	
252	  insert into public.transaction_payments (
253	    transaction_id, method, amount, received, change
254	  ) values (
255	    v_transaction_id, p_payment_method, v_subtotal, p_received, v_change
256	  );
257	
258	  return query select v_transaction_id, v_invoice_number;
259	end;
260	$$;
261	
262	grant execute on function public.checkout_transaction(uuid, uuid, jsonb, text, numeric) to authenticated;
