97	export type TicketCategoryState = { error: string | null };
98	
99	type ParsedTicketCategoryFields =
100	  | { error: string }
101	  | {
102	      error: null;
103	      name: string;
104	      priceWeekday: number;
105	      priceHoliday: number;
106	      memberPrice: number;
107	      groupMinQty: number;
108	      groupPrice: number | null;
109	    };
110	
111	function parseTicketCategoryFields(formData: FormData): ParsedTicketCategoryFields {
112	  const name = (formData.get("name") as string)?.trim();
113	  const priceWeekday = Number(formData.get("priceWeekday"));
114	  const priceHoliday = Number(formData.get("priceHoliday"));
115	  const memberPrice = Number(formData.get("memberPrice"));
116	  const groupMinQtyRaw = (formData.get("groupMinQty") as string)?.trim();
117	  const groupPriceRaw = (formData.get("groupPrice") as string)?.trim();
118	
119	  if (!name) return { error: "Nama kategori wajib diisi." };
120	  if (Number.isNaN(priceWeekday) || priceWeekday < 0) {
121	    return { error: "Harga hari kerja harus angka dan tidak boleh negatif." };
122	  }
123	  if (Number.isNaN(priceHoliday) || priceHoliday < 0) {
124	    return { error: "Harga hari libur harus angka dan tidak boleh negatif." };
125	  }
126	  if (Number.isNaN(memberPrice) || memberPrice < 0) {
127	    return { error: "Harga member harus angka dan tidak boleh negatif." };
128	  }
129	
130	  const groupMinQty = groupMinQtyRaw ? Number(groupMinQtyRaw) : 0;
131	  if (Number.isNaN(groupMinQty) || groupMinQty < 0) {
132	    return { error: "Minimal qty rombongan harus angka dan tidak boleh negatif." };
133	  }
134	  const groupPrice = groupPriceRaw ? Number(groupPriceRaw) : null;
135	  if (groupPrice !== null && (Number.isNaN(groupPrice) || groupPrice < 0)) {
136	    return { error: "Harga rombongan harus angka dan tidak boleh negatif." };
137	  }
138	
139	  return { error: null, name, priceWeekday, priceHoliday, memberPrice, groupMinQty, groupPrice };
140	}
