148	  if (parsed.error !== null) return { error: parsed.error };
149	
150	  const supabase = await createClient();
151	  const { error } = await supabase.from("ticket_categories").insert({
152	    business_id: businessId,
153	    name: parsed.name,
154	    price_weekday: parsed.priceWeekday,
155	    price_holiday: parsed.priceHoliday,
156	    member_price: parsed.memberPrice,
157	    group_min_qty: parsed.groupMinQty,
158	    group_price: parsed.groupPrice,
159	  });
160	
161	  if (error) {
162	    if (error.code === "23505") {
163	      return { error: "Nama kategori sudah dipakai." };
164	    }
165	    return { error: error.message };
166	  }
167	
168	  await logActivity(
169	    supabase,
170	    businessId,
171	    "pengaturan",
172	    "sukses",
173	    `Kategori tiket baru: ${parsed.name}`,
174	  );
175	  revalidatePath(`/business/${businessId}/settings`);
176	  return { error: null };
177	}
