179	export async function updateTicketCategory(
180	  businessId: string,
181	  categoryId: string,
182	  _prevState: TicketCategoryState,
183	  formData: FormData,
184	): Promise<TicketCategoryState> {
185	  const parsed = parseTicketCategoryFields(formData);
186	  if (parsed.error !== null) return { error: parsed.error };
187	
188	  const supabase = await createClient();
189	  const { error } = await supabase
