1	import net from "node:net";
2	import type { SupabaseClient } from "@supabase/supabase-js";
3	import { buildKitchenTicket, type KitchenTicketItem } from "./escpos";
4	
5	export type KitchenPrintJob = {
6	  source: string;
7	  label: string;
8	  items: (KitchenTicketItem & { category: string | null })[];
9	};
10	
11	export type KitchenPrintResult = { printer: string; ok: boolean; error?: string };
12	
13	function sendToLanPrinter(address: string, data: Buffer, timeoutMs = 3000): Promise<void> {
14	  return new Promise((resolve, reject) => {
15	    const [host, portStr] = address.split(":");
16	    const port = portStr ? Number(portStr) : 9100;
17	    const socket = new net.Socket();
18	    let settled = false;
19	
20	    const finish = (err?: Error) => {
21	      if (settled) return;
22	      settled = true;
23	      clearTimeout(timer);
24	      socket.destroy();
25	      if (err) reject(err);
26	      else resolve();
27	    };
28	
29	    const timer = setTimeout(() => finish(new Error("Timeout menghubungi printer")), timeoutMs);
30	
31	    socket.once("error", (err) => finish(err));
32	    socket.connect(port, host, () => {
33	      // Success once the bytes are flushed to the OS socket buffer — most
34	      // thermal printers don't close their end after receiving a job, so
35	      // waiting for a "close" event here would misreport every print as a
36	      // timeout even when the ticket printed fine.
37	      socket.write(data, (err) => finish(err ?? undefined));
38	    });
39	  });
40	}
41	
42	// Best-effort: printer failures must never fail the sale/order that triggered them.
43	export async function dispatchKitchenPrint(
44	  supabase: SupabaseClient,
45	  businessId: string,
46	  job: KitchenPrintJob,
47	): Promise<KitchenPrintResult[]> {
48	  if (job.items.length === 0) return [];
49	
50	  const { data: printers } = await supabase
51	    .from("kitchen_printers")
52	    .select("id, name, categories, connection_type, address")
53	    .eq("business_id", businessId);
54	
55	  const lanPrinters = (printers ?? []).filter(
56	    (p) => p.connection_type === "lan" && !!p.address,
57	  ) as { id: string; name: string; categories: string[]; connection_type: "lan"; address: string }[];
58	
59	  const attempts = lanPrinters
60	    .map((printer) => {
61	      const items =
62	        printer.categories.length > 0
63	          ? job.items.filter((i) => i.category && printer.categories.includes(i.category))
64	          : job.items;
65	      return { printer, items };
66	    })
67	    .filter((a) => a.items.length > 0);
68	
69	  const results = await Promise.all(
70	    attempts.map(async ({ printer, items }): Promise<KitchenPrintResult> => {
71	      try {
72	        const buffer = buildKitchenTicket({
73	          station: printer.name,
74	          source: job.source,
75	          label: job.label,
76	          items,
77	        });
78	        await sendToLanPrinter(printer.address, buffer);
79	        return { printer: printer.name, ok: true };
80	      } catch (err) {
81	        return { printer: printer.name, ok: false, error: err instanceof Error ? err.message : String(err) };
82	      }
83	    }),
84	  );
85	
86	  return results;
87	}
