141	async function printKitchenTicketsForItems(
142	  supabase: Awaited<ReturnType<typeof createClient>>,
143	  businessId: string,
144	  source: string,
145	  label: string,
146	  items: { productId: string; qty: number; note?: string | null }[],
147	) {
